fn solve_rival_distance(n: i8, x: i8, a: i8, b: i8) -> i8 {
    // Compute the current distance
    let diff = (a - b).abs() as i16;
    // Add available moves
    let total = diff + x as i16;
    // The maximum possible distance on a line of length n is n-1
    let max_dist = (n - 1) as i16;
    // Clamp to [0, n-1] and cast back
    total.min(max_dist) as i8
}

